#---------------------------------------------------------
#--this file is used to evaluate the experiment results
#--generated by the ExperimentPart.
#---------------------------------------------------------

import os
import torch
import numpy as np

from sklearn.metrics import (
    precision_score,
    recall_score,
    f1_score
)


class Evaluation:

    def __init__(
        self,
        data_loader
    ):

        #--store the experiment data loader.
        self.data_loader = data_loader

        #--get the experiment information from the data loader.
        self.experiment_name = (
            self.data_loader.experiment_name
        )

        self.experiment_id = (
            self.data_loader.experiment_id
        )

        self.experiment_data_path = (
            self.data_loader.experiment_data_path
        )


    #--calculate the evaluation metrics for a single run.
    def _calculate_one_run_metrics(self, run_info):
        """Calculate the evaluation metrics for a single run."""

        test_accuracy = run_info["test_accuracy"]
        y_true = run_info["y_true"]
        y_pred = run_info["y_pred"]

        #--use the test accuracy directly from the experiment results.
        accuracy = test_accuracy

        #--calculate macro precision.
        precision = precision_score(
            y_true,
            y_pred,
            average="macro"
        )

        #--calculate macro recall.
        recall = recall_score(
            y_true,
            y_pred,
            average="macro"
        )

        #--calculate macro F1 score.
        f1 = f1_score(
            y_true,
            y_pred,
            average="macro"
        )

        run_metrics = {
            "accuracy": accuracy,
            "precision": precision,
            "recall": recall,
            "f1": f1
        }

        return run_metrics


    #--calculate the evaluation metrics for all runs.
    def _calculate_all_run_metrics(self, run_level_view):
        """Calculate the evaluation metrics for all runs."""

        all_run_metrics = []

        for run_info in run_level_view:

            run_metrics = self._calculate_one_run_metrics(
                run_info
            )

            all_run_metrics.append(
                run_metrics
            )

        return all_run_metrics


    #--aggregate the evaluation metrics across all runs.
    def _aggregate_metrics(self, all_run_metrics):
        """Aggregate the evaluation metrics across all runs."""

        metric_names = [
            "accuracy",
            "precision",
            "recall",
            "f1"
        ]

        aggregated_metrics = {}

        for metric_name in metric_names:

            metric_values = [
                run_metrics[metric_name]
                for run_metrics in all_run_metrics
            ]

            metric_mean = np.mean(metric_values)

            metric_std = np.std(
                metric_values,
                ddof=1
            )

            aggregated_metrics[metric_name] = {
                "mean": metric_mean,
                "std": metric_std
            }

        return aggregated_metrics


    #--build and save the evaluation results.
    def _build_evaluation_results(self, aggregated_metrics):
        """Build and save the evaluation results."""

        #--build the evaluation result name.
        evaluation_result_name = (
            f"{self.experiment_name}_{self.experiment_id}"
        )

        #--build the evaluation results.
        evaluation_results = {
            "experiment_info": {
                "experiment_id": self.experiment_id,
                "experiment_name": self.experiment_name,
                "evaluation_result_name": evaluation_result_name
            },

            "evaluation_info": {
                "metrics": [
                    "accuracy",
                    "precision",
                    "recall",
                    "f1"
                ],
                "accuracy_source": "test_accuracy",
                "precision_average": "macro",
                "recall_average": "macro",
                "f1_average": "macro",
                "aggregation": "mean_std"
            },

            "results": aggregated_metrics
        }

        #--print the evaluation results in the terminal.
        print("\nEvaluation Results")
        print(
            "| Experiment | Accuracy | Precision | Recall | F1 |"
        )
        print(
            "|------------|----------|-----------|--------|----|"
        )

        print(
            f"| {evaluation_result_name} | "
            f"{aggregated_metrics['accuracy']['mean']:.3f}±"
            f"{aggregated_metrics['accuracy']['std']:.3f} | "
            f"{aggregated_metrics['precision']['mean']:.3f}±"
            f"{aggregated_metrics['precision']['std']:.3f} | "
            f"{aggregated_metrics['recall']['mean']:.3f}±"
            f"{aggregated_metrics['recall']['std']:.3f} | "
            f"{aggregated_metrics['f1']['mean']:.3f}±"
            f"{aggregated_metrics['f1']['std']:.3f} |"
        )

        #--build the path of the evaluation results file.
        experiment_dir = os.path.join(
            self.experiment_data_path,
            f"{self.experiment_name}_{self.experiment_id}"
        )

        evaluation_results_path = os.path.join(
            experiment_dir,
            "EvaluationResults.pt"
        )

        #--save the evaluation results.
        torch.save(
            evaluation_results,
            evaluation_results_path
        )

        return evaluation_results


    #--run the evaluation process.
    def run(self):
        """Run the complete evaluation process."""

        #--get the run-level view from the experiment data loader.
        _, run_level_view = self.data_loader.run()

        #--calculate the evaluation metrics for all runs.
        all_run_metrics = self._calculate_all_run_metrics(
            run_level_view
        )

        #--aggregate the metrics across all runs.
        aggregated_metrics = self._aggregate_metrics(
            all_run_metrics
        )

        #--build and save the evaluation results.
        evaluation_results = self._build_evaluation_results(
            aggregated_metrics
        )

        return evaluation_results